import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.C588jwcu.js";const h=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"ko/latest/tutorial/core/logger.md","filePath":"ko/latest/tutorial/core/logger.md","lastUpdated":1785683504000}'),d={name:"ko/latest/tutorial/core/logger.md"};function c(l,e,g,_,s,i){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="로거-knd-logger" tabindex="-1">로거 KND_Logger <a class="header-anchor" href="#로거-knd-logger" aria-label="Permalink to &quot;로거 KND_Logger&quot;">​</a></h1><h2 id="머리말" tabindex="-1">머리말 <a class="header-anchor" href="#머리말" aria-label="Permalink to &quot;머리말&quot;">​</a></h2><p>KND_Logger는 Godot Logger 구현을 기반으로 한 로그 모듈입니다. 로그 레벨, 로그 형식, 로그 출력, 로그 파일 등의 기능을 지원하며 Konado 실행 중의 로그 정보를 기록하는 데 사용됩니다.</p><h2 id="로그-경로" tabindex="-1">로그 경로 <a class="header-anchor" href="#로그-경로" aria-label="Permalink to &quot;로그 경로&quot;">​</a></h2><p>로그 파일의 논리 경로는 <code>user://konado_log.log</code>입니다. 실제 디렉터리는 현재 운영 체제와 프로젝트 이름에 따라 Godot가 결정하며 <code>OS.get_user_data_dir()</code>로 확인할 수 있습니다. <code>LOG_FILE_PATH</code>는 기본 상수이므로 경로를 변경하려면 사용자 지정 플러그인 버전에서 이 상수를 관리해야 합니다.</p><h2 id="화면-오버레이-로그" tabindex="-1">화면 오버레이 로그 <a class="header-anchor" href="#화면-오버레이-로그" aria-label="Permalink to &quot;화면 오버레이 로그&quot;">​</a></h2><p>오류가 발생하면 대화 장면은 화면 위에 로그 창을 덮어 표시하여 오류 정보를 보여 주고 게임 실행을 중단합니다. 이 기능을 끄고 싶다면 <code>KND_DialogueManager</code>의 <code>enable_overlay_log</code> 속성을 <code>false</code>로 설정하세요.</p><h2 id="로그-콜백" tabindex="-1">로그 콜백 <a class="header-anchor" href="#로그-콜백" aria-label="Permalink to &quot;로그 콜백&quot;">​</a></h2><p><code>KND_Logger</code> 인스턴스는 <code>error_caught(msg)</code>와 <code>message_caught(message, error)</code> 신호를 보냅니다. <code>KND_DialogueManager</code>는 씬 트리에 들어갈 때 내부 로거를 만들어 Godot에 등록하고 <code>error_caught</code>로 화면 오버레이를 구동합니다. 로거는 전역 자동 로드 객체가 아닙니다. 별도의 <code>KND_Logger</code>를 만드는 사용자 지정 연동은 <code>OS.add_logger()</code>로 등록하고 해제 전에 <code>OS.remove_logger()</code>를 호출하여 중복 기록이나 유효하지 않은 인스턴스가 남지 않게 해야 합니다.</p>',9)])])}const u=o(d,[["render",c]]);export{h as __pageData,u as default};
